suppressPackageStartupMessages({library(Seurat);library(ggplot2)})
options(stringsAsFactors=FALSE);set.seed(20260924);source("PIPELINE_V2/config/paths.R")
cat("\n=== 06A2 LINEAGE CONTAMINATION AUDIT ===\n")
IN<-file.path(V2_FROZEN,"global_atlas_v2_frozen.rds");OUT<-file.path(V2_ROOT,"results","annotation","06_GLOBAL_L1","contamination_audit");TD<-file.path(OUT,"tables");FD<-file.path(OUT,"figures");dir.create(TD,recursive=TRUE,showWarnings=FALSE);dir.create(FD,recursive=TRUE,showWarnings=FALSE)
x<-readRDS(IN);DefaultAssay(x)<-"RNA";CC<-"RNA_snn_res.0.6";x$global_cluster<-factor(as.character(x@meta.data[[CC]]),levels=as.character(0:26));stopifnot(ncol(x)==82893,nrow(x)==23412)
programs<-list(Epithelial=c("KRT5","KRT14","KRT15","KRT17","KRT1","KRT10","KRT19","EPCAM"),Fibroblast=c("COL1A1","COL1A2","COL3A1","DCN","LUM","PDGFRA"),Vascular_EC=c("PECAM1","VWF","KDR","CDH5","EMCN","ENG"),Lymphatic_EC=c("PROX1","PDPN","FLT4","CCL21","LYVE1"),Pericyte=c("RGS5","CSPG4","MCAM","NOTCH3","PDGFRB","ABCC9"),Smooth_muscle=c("ACTA2","TAGLN","MYH11","CNN1","MYL9","ACTG2"),Lymphocyte=c("PTPRC","CD3D","CD3E","TRBC1","TRBC2","NKG7","GNLY"),Myeloid_DC=c("PTPRC","LST1","TYROBP","FCER1G","HLA-DRA","CD74","CTSS"),Melanocyte=c("PMEL","MLANA","TYR","DCT","MITF"),Sebaceous=c("PPARG","PLIN2","KRT79","MGST1","FASN","AWAT2","MOGAT1"),Sweat_gland=c("AQP5","DCD","PIP","KRT8","KRT18","KRT19","FOXA1"),Neural_Schwann=c("S100B","SOX10","PLP1","MPZ","S100A1"))
programs<-lapply(programs,function(g)intersect(g,rownames(x)));cov<-data.frame(lineage=names(programs),n_present=vapply(programs,length,integer(1)));write.csv(cov,file.path(TD,"06A2_marker_coverage.csv"),row.names=FALSE)
expr<-LayerData(x,assay="RNA",layer="data");S<-sapply(programs,function(g)Matrix::colMeans(expr[g,,drop=FALSE]));Z<-scale(S);Z[!is.finite(Z)]<-0
ord<-t(apply(Z,1,function(v)order(v,decreasing=TRUE)[1:2]));i1<-ord[,1];i2<-ord[,2];top1<-colnames(Z)[i1];top2<-colnames(Z)[i2];s1<-Z[cbind(seq_len(nrow(Z)),i1)];s2<-Z[cbind(seq_len(nrow(Z)),i2)]
cell<-data.frame(cell_id=rownames(Z),global_cluster=as.character(x$global_cluster),patient_id=x$patient_id,disease=x$disease,batch=x$batch,top1_lineage=top1,top2_lineage=top2,top1_z=s1,top2_z=s2,lineage_margin=s1-s2,nCount_RNA=x$nCount_RNA,nFeature_RNA=x$nFeature_RNA,percent_mt=x$percent.mt,doublet_score=x$doublet_score)
con<-gzfile(file.path(TD,"06A2_cell_lineage_scores.csv.gz"),"wt");write.csv(cell,con,row.names=FALSE);close(con)
cls<-as.character(0:26);CS<-matrix(NA,27,ncol(Z),dimnames=list(cls,colnames(Z)));DF<-CS*0
for(cl in cls){ii<-which(cell$global_cluster==cl);CS[cl,]<-colMeans(Z[ii,,drop=FALSE]);tt<-table(factor(cell$top1_lineage[ii],levels=colnames(Z)));DF[cl,]<-as.numeric(tt)/length(ii)}
write.csv(data.frame(global_cluster=rownames(CS),CS),file.path(TD,"06A2_cluster_lineage_score_matrix.csv"),row.names=FALSE);write.csv(data.frame(global_cluster=rownames(DF),DF),file.path(TD,"06A2_cluster_dominant_lineage_fraction.csv"),row.names=FALSE)
pairs<-list(c("Epithelial","Fibroblast"),c("Epithelial","Vascular_EC"),c("Epithelial","Lymphatic_EC"),c("Epithelial","Lymphocyte"),c("Epithelial","Myeloid_DC"),c("Fibroblast","Lymphocyte"),c("Fibroblast","Myeloid_DC"),c("Vascular_EC","Lymphocyte"),c("Vascular_EC","Myeloid_DC"),c("Lymphatic_EC","Lymphocyte"),c("Lymphatic_EC","Myeloid_DC"),c("Melanocyte","Lymphocyte"),c("Melanocyte","Myeloid_DC"),c("Neural_Schwann","Lymphocyte"),c("Neural_Schwann","Myeloid_DC"))
det<-lapply(programs,function(g)Matrix::colSums(expr[g,,drop=FALSE]>0));mixed_any<-rep(FALSE,ncol(x));cr<-list()
for(k in seq_along(pairs)){a<-pairs[[k]][1];b<-pairs[[k]][2];m<-det[[a]]>=2 & det[[b]]>=2;mixed_any<-mixed_any|m;for(cl in cls){ii<-which(as.character(x$global_cluster)==cl);cr[[length(cr)+1]]<-data.frame(global_cluster=as.integer(cl),lineage_A=a,lineage_B=b,n_cells=length(ii),n_mixed=sum(m[ii]),fraction_mixed=mean(m[ii]))}}
co<-do.call(rbind,cr);write.csv(co,file.path(TD,"06A2_incompatible_coexpression.csv"),row.names=FALSE)
rows<-lapply(cls,function(cl){ii<-which(cell$global_cluster==cl);v<-CS[cl,];o<-order(v,decreasing=TRUE);data.frame(global_cluster=as.integer(cl),n_cells=length(ii),top_lineage=names(v)[o[1]],second_lineage=names(v)[o[2]],top_cluster_z=v[o[1]],second_cluster_z=v[o[2]],cluster_margin=v[o[1]]-v[o[2]],fraction_cells_top1_agree=mean(cell$top1_lineage[ii]==names(v)[o[1]]),median_cell_margin=median(cell$lineage_margin[ii]),median_nCount=median(cell$nCount_RNA[ii]),median_nFeature=median(cell$nFeature_RNA[ii]),median_doublet_score=median(cell$doublet_score[ii],na.rm=TRUE),fraction_incompatible_multigene=mean(mixed_any[ii]),n_patients=length(unique(cell$patient_id[ii])),max_patient_fraction=max(prop.table(table(cell$patient_id[ii]))),max_batch_fraction=max(prop.table(table(cell$batch[ii]))))})
tab<-do.call(rbind,rows);gd<-median(cell$doublet_score,na.rm=TRUE);q90d<-quantile(cell$doublet_score,.9,na.rm=TRUE,names=FALSE);q90f<-quantile(cell$nFeature_RNA,.9,names=FALSE)
tab$flag_low_lineage_agreement<-tab$fraction_cells_top1_agree<.60;tab$flag_low_cluster_margin<-tab$cluster_margin<.25;tab$flag_incompatible_coexpression<-tab$fraction_incompatible_multigene>.10;tab$flag_doublet_enrichment<-tab$median_doublet_score>q90d;tab$flag_high_complexity<-tab$median_nFeature>q90f
focus<-c(2,8,10,13,14,15,17,21);tab$flag_focus_manual<-tab$global_cluster%in%focus;tab$audit_status<-ifelse(tab$flag_low_lineage_agreement|tab$flag_low_cluster_margin|tab$flag_incompatible_coexpression|tab$flag_doublet_enrichment|tab$flag_high_complexity,"REVIEW","CLEAN_OR_COMPATIBLE")
write.csv(tab,file.path(TD,"06A2_cluster_lineage_audit.csv"),row.names=FALSE);write.csv(tab[tab$flag_focus_manual|tab$audit_status=="REVIEW",],file.path(TD,"06A2_focus_clusters.csv"),row.names=FALSE)
h<-as.data.frame(as.table(CS));names(h)<-c("cluster","lineage","mean_z");h$cluster<-factor(h$cluster,levels=rev(cls))
p1<-ggplot(h,aes(lineage,cluster,fill=mean_z))+geom_tile()+scale_fill_gradient2(low="#2166AC",mid="white",high="#B2182B",midpoint=0)+labs(x=NULL,y="Global cluster",fill="Mean z",title="Lineage-program evidence")+theme_classic(base_size=10)+theme(axis.text.x=element_text(angle=45,hjust=1))
ggsave(file.path(FD,"06A2_lineage_score_heatmap.pdf"),p1,width=10,height=8,bg="white");ggsave(file.path(FD,"06A2_lineage_score_heatmap.png"),p1,width=10,height=8,dpi=600,bg="white")
h2<-as.data.frame(as.table(DF));names(h2)<-c("cluster","lineage","fraction");h2$cluster<-factor(h2$cluster,levels=rev(cls))
p2<-ggplot(h2,aes(lineage,cluster,fill=fraction))+geom_tile()+scale_fill_gradient(low="white",high="black",limits=c(0,1))+labs(x=NULL,y="Global cluster",fill="Fraction",title="Fraction of cells with each dominant lineage")+theme_classic(base_size=10)+theme(axis.text.x=element_text(angle=45,hjust=1))
ggsave(file.path(FD,"06A2_dominant_lineage_fraction.pdf"),p2,width=10,height=8,bg="white");ggsave(file.path(FD,"06A2_dominant_lineage_fraction.png"),p2,width=10,height=8,dpi=600,bg="white")
writeLines(c("PIPELINE_V2 — 06A2 lineage contamination audit",paste0("Cells: ",ncol(x)),paste0("Clusters: ",length(cls)),paste0("Clusters flagged REVIEW: ",sum(tab$audit_status=="REVIEW")),"No cells removed. No identities changed.","REVIEW is an audit flag, not a biological conclusion.","Compatible adjacent programs (e.g. pericyte/SMC; epithelial/glandular) are not treated as incompatible pairs."),file.path(TD,"06A2_audit.txt"))
cat("\n=== CLUSTER AUDIT ===\n");print(tab[,c("global_cluster","top_lineage","second_lineage","cluster_margin","fraction_cells_top1_agree","fraction_incompatible_multigene","median_doublet_score","audit_status")],row.names=FALSE)
cat("\nPASS — audit only; frozen atlas unchanged.\n")
